{"skill": "async (b) => {
  const items = await b.items();
  const findSlot = (name) => { const it = items.find(i => i.name && i.name.toLowerCase().includes(name)); return it ? it.slot : -1; };
  const hoe = findSlot('hoe');
  const can = findSlot('watering');
  const seed = findSlot('parsnip');
  if (hoe < 0 || can < 0 || seed < 0) { b.log('missing tool'); return false; }
  const tiles = [];
  for (let y = 3; y <= 5; y++) for (let x = 7; x <= 9; x++) tiles.push([x, y]);
  for (const [x, y] of tiles) {
    const r1 = await b.workTile(x, y, hoe, 'ControllerA');
    b.log('till ' + x + ',' + y + ' ' + JSON.stringify(r1));
    const r2 = await b.workTile(x, y, seed, 'ControllerA');
    b.log('plant ' + x + ',' + y + ' ' + JSON.stringify(r2));
    const r3 = await b.workTile(x, y, can, 'ControllerA');
    b.log('water ' + x + ',' + y + ' ' + JSON.stringify(r3));
  }
  return true;
}", "check": "async (b) => {
  const obs = await b.observe();
  const txt = String(obs);
  let count = 0;
  for (let y = 3; y <= 5; y++) for (let x = 7; x <= 9; x++) {
    const re = new RegExp('\\(?' + x + '\\s*,\\s*' + y + '\\)?[^\\n]*parsnip', 'i');
    if (re.test(txt)) count++;
  }
  return { ok: count >= 6, detail: 'watered parsnips detected: ' + count };
}"}
